    <script>document.addEventListener('DOMContentLoaded',()=>{const input=document.querySelector('[data-catalog-filter]'),select=document.querySelector('[data-catalog-options]');if(input&&select){const options=[...select.querySelectorAll('option')];input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();options.forEach(option=>{if(!option.value)return;option.hidden=query!==''&&!option.textContent.toLowerCase().includes(query);});});}document.querySelector('[data-first-error]')?.focus();});</script>
</x-layouts.office>
